    'nav_help'             => 'Help',
    'help_meta_title'      => 'dopeIPTV help — setup, playback, recording, troubleshooting',
    'help_meta_desc'       => 'How to set up and use dopeIPTV: playlists, the programme guide, timeshift, recording, multiview, your own files, casting, and what to do when something goes wrong.',
    'help_h1'              => 'Help',
    'help_intro'           => 'Everything is on this page with its answer open. Type to narrow it down — press “/” anywhere on the page to jump to the box.',
